##================================================================================================================
## Simple PyROOT script to plot the "trend" of bytes generated by an 8-bit Linear-Feedback Shift Register (LFSR).
## The "random" sequence repeats after 256 values, fill the histogram to show only the first 4 replicated sequences.
##
## Command line usage:
##
##   % cd /path/to/lab9
##   % python -i bin/hBytes.py
##
## By default the script assumes to process "work/sim/LFSR.txt", but you can also start Python from another directory
## and specify a different target file. As an example:
##
##   % cd /path/to/lab9/test
##   % python -i ../bin/hBytes.py ../work/sim/LFSR.txt
##
## Luca Pacher - pacher@to.infn.it
## Spring 2020
##================================================================================================================

## Python standard libraries

## ROOT components
import ROOT

## parse input file

fileName = "work/sim/LFSR.txt"

filePtr = open(fileName,"r")

## check if file exists

"""

   // open file handler
   ifstream filePtr ;

   filePtr.open(fileName,"r")

   if (!filePtr) {

      std::cout << "\n**ERROR: " << fileName << " Not such file or directory. Force an exit now." << std::endl ;

      // script failure
      exit(1) ;
    }

"""

## don't show the statistics box 
ROOT.gStyle.SetOptStat(0)

## histogram the "trend" of shift-register outputs (not a true histogram indeed, just a trend)
hRandom = ROOT.TH1I("hRandom", "LFSR output-code vs. tick", 256*4, -0.5, 256*4 + 0.5) ;   #extra values simply goes into overflow bin

## histogram of the distribution
hCode = ROOT.TH1I("hCode", "LFSR output-code distribution", 256, -0.5, 255 + 0.5)

bin = 1

for line in filePtr :

   value = int(line.split("\n")[0])

   ## **DEBUG
   #print(value)

   hRandom.SetBinContent(bin,value)
   hCode.Fill(value)

   bin = bin + 1


## close file handler
filePtr.close()


################################
##   "trend" histogram plot   ##
################################

c1 = ROOT.TCanvas("c1")

c1.cd()
hRandom.Draw()

## the "random" sequence repeats after 256 values, show only 4 repeated sequences
hRandom.GetXaxis().SetRangeUser(0, 256*4)

## cosmetics
hRandom.GetXaxis().SetTitle("tick")
hRandom.GetYaxis().SetTitle("LFSR[7:0] integer value")
hRandom.GetYaxis().CenterTitle()

ROOT.gPad.SetGridx()
ROOT.gPad.SetGridy()

## set y-axis log scale for easier pattern recognition
#ROOT.gPad.SetLogy()
ROOT.gPad.Modified()
ROOT.gPad.Update()


#########################################
##  code distribution histogram plot   ##
#########################################

c2 = ROOT.TCanvas("c2")
c2.cd()

hCode.SetStats(1) ;   #display the statistics box
ROOT.gStyle.SetOptStat("emrou") ;   #only show number of entries, mean, RMS and underflow/overflow in the statistics box

hCode.SetFillStyle(0)
hCode.Draw("BAR")

## cosmetics
hCode.GetXaxis().SetTitle("LFSR[7:0] integer value")
hCode.GetYaxis().SetTitle("entries / code")
hCode.GetYaxis().CenterTitle()

Nentries = hCode.GetEntries()

hCode.GetYaxis().SetRangeUser(0, int(Nentries/255) + 20)

#ROOT.gPad.SetGridx() ;
#ROOT.gPad.SetGridy() ;

ROOT.gPad.RedrawAxis()

ROOT.gPad.Modified()
ROOT.gPad.Update()

